    // Throttle preview RAF only; explicit fixed-timestamp export frames are unchanged.
    const request=window.requestAnimationFrame.bind(window),cancel=window.cancelAnimationFrame.bind(window),pending=new Map<number,{timer:number;frame?:number}>();let next=0;
    window.requestAnimationFrame=callback=>{const id=++next,entry={timer:0,frame:undefined as number|undefined};entry.timer=window.setTimeout(()=>{entry.frame=request(time=>{pending.delete(id);callback(time);});},2000);pending.set(id,entry);return id;};
    window.cancelAnimationFrame=id=>{const entry=pending.get(id);if(entry){clearTimeout(entry.timer);if(entry.frame!==undefined)cancel(entry.frame);pending.delete(id);}};
