async function pinch(page:Page,action:string){
  const target=await page.evaluate(action=>{for(const surface of JSON.parse(document.body.dataset.studioSurfaces||'[]')){const button=surface.buttons.find((button:any)=>button.action===action);if(button)return {x:surface.position[0]+((button.x+button.width/2)/surface.canvas[0]-.5)*surface.size[0],y:surface.position[1]+(.5-(button.y+button.height/2)/surface.canvas[1])*surface.size[1],z:surface.position[2]};}return null;},action);expect(target,action).not.toBeNull();
  await page.evaluate(async target=>{
    const frame=()=>new Promise<void>((resolve,reject)=>{const previous=document.body.dataset.studioFrame,observer=new MutationObserver(()=>{if(document.body.dataset.studioFrame!==previous){observer.disconnect();clearTimeout(timer);resolve();}}),timer=setTimeout(()=>{observer.disconnect();reject(new Error('No studio XR frame'));},10000);observer.observe(document.body,{attributes:true,attributeFilter:['data-studio-frame']});});
    const hand=(window as any).xrDevice.hands.right;hand.position.set(.25,1.3,-.4);const dx=target!.x-.25,dy=target!.y-1.3,dz=target!.z-3.2,length=Math.hypot(dx,dy,dz),vx=dx/length,vy=dy/length,vz=dz/length,w=1-vz,q=Math.hypot(vy,-vx,w);hand.quaternion.set(vy/q,-vx/q,0,w/q);
    await frame();hand.updatePinchValue(1);await frame();await frame();hand.updatePinchValue(0);await frame();await frame();
  },target);
}
