test('opening camera flies into the set then cuts as the host turns, with deterministic portrait framing',()=>{
  const host=new THREE.Vector3(-1.35,1.25,-2.12),camera=new THREE.PerspectiveCamera();
  const first=openingCameraPose(camera,0,host);expect(first.phase).toBe('fly-in');const far=camera.position.distanceTo(host);
  const near=openingCameraPose(camera,3000,host);expect(camera.position.distanceTo(host)).toBeLessThan(far);expect(near.hostYaw).toBeLessThan(first.hostYaw);
  const close=openingCameraPose(camera,4000,host,.5625);expect(close.phase).toBe('camera-two');expect(close.hostYaw).toBeLessThan(0);const pose=camera.position.toArray();
  openingCameraPose(camera,4000,host,.5625);expect(camera.position.toArray()).toEqual(pose);expect(camera.aspect).toBe(.5625);
});

