test('offline soundtrack renders a louder intro and outro with a modest bed and safe peaks',async({page})=>{
 const tone=(amplitude:number)=>{const wave=studioWav(8000);for(let i=0;i<(wave.length-44)/2;i++)wave.writeInt16LE(Math.round(amplitude*32767*Math.sin(i/24000*Math.PI*2*440)),44+i*2);return wave;};
 await page.route('**/audio/news-theme.mp3',route=>route.fulfill({body:tone(.4),contentType:'audio/wav'}));await page.goto('/audio/CREDITS.txt');await page.evaluate(()=>document.body.innerHTML='<button>Start audio test</button>');await page.getByRole('button',{name:'Start audio test'}).click();
 const result=await page.evaluate(async({silent,loud})=>{const {StudioTimeline}=await import('/src/studio-timeline.ts'),timeline=new StudioTimeline(()=>{}),runId=crypto.randomUUID(),actor=crypto.randomUUID(),take:any={id:crypto.randomUUID(),castSnapshots:[{id:actor,name:'Host'}],productionSnapshot:{runId,writer:{},turns:[0,1,2].map((n)=>({id:crypto.randomUUID(),beatId:'line-'+n,runId,characterId:actor,startMs:n*8000,durationMs:n===2?2000:8000,voiceAssetId:String(n).repeat(64),intent:n===2?'closing':'statement',text:'A recorded line.',characterSnapshot:{name:'Host'}}))}};
 await timeline.load(take,async()=>({audio:silent,mime:'audio/wav'}) as any);const music=await timeline.exportAudio(true),rms=(audio:AudioBuffer,time:number)=>{const data=audio.getChannelData(0),start=Math.round(time*audio.sampleRate),count=Math.round(.25*audio.sampleRate);let sum=0;for(let i=start;i<start+count&&i<data.length;i++)sum+=data[i]*data[i];return Math.sqrt(sum/count);};const levels={intro:rms(music,1),bed:rms(music,10),outro:rms(music,19.5),tail:rms(music,23.7)};await timeline.dispose();const hot=new StudioTimeline(()=>{});await hot.load(take,async()=>({audio:loud,mime:'audio/wav'}) as any);const mixed=await hot.exportAudio(true);let peak=0;for(const value of mixed.getChannelData(0))peak=Math.max(peak,Math.abs(value));await hot.dispose();return {...levels,peak};},{silent:studioWav(8000).toString('base64'),loud:tone(.95).toString('base64')});
 expect(result.intro).toBeGreaterThan(result.bed*2.5);expect(result.outro).toBeGreaterThan(result.bed*2.5);expect(result.tail).toBeLessThan(result.bed*.2);expect(result.peak).toBeLessThanOrEqual(.98001);
});

